<script setup lang="ts">
import {FileText,CheckCircle2,Clock3,AlertTriangle,Layers3,Users,ChartColumn,CalendarDays,ChevronRight,ArrowRight,Plus,Printer,Megaphone,Search,RefreshCw,ShieldCheck,Building2,BellRing,Sparkles} from 'lucide-vue-next'
import {statusNames,statusClass,fmtDate,procName,type Dossier,type Procedure,type UserInfo} from '~/composables/useCommune'
const props=defineProps<{user:UserInfo;stats:Record<string,number>;dossiers:Dossier[];procedures:Procedure[];crossStats:any[];appointments:any[];services:Record<string,string>}>()
const emit=defineEmits<{(e:'navigate',value:string):void;(e:'refresh'):void}>()
const {api,errText}=useCommune()
const selected=ref<any>(null),loading=ref(false),search=ref(''),tab=ref('all'),notice=ref('')
const role=computed(()=>props.user.role)
const headlineStats=computed(()=>{
 const s=props.stats
 const item=(label:string,value:any,icon:any,color:string,foot='')=>({label,value:value??0,icon,color,foot})
 switch(role.value){
 case 'citizen':return [item('Hồ sơ đang theo dõi',s.processing,FileText,'blue'),item('Đã hoàn thành',s.completed,CheckCircle2,'green'),item('Cần bổ sung',props.dossiers.filter(x=>x.status==='need_supplement').length,AlertTriangle,'orange'),item('Lịch hẹn sắp tới',props.appointments.length,CalendarDays,'red'),item('Thủ tục đã dùng',new Set(props.dossiers.map(x=>x.procedure_code)).size,Layers3,'purple')]
 case 'receptionist':return [item('Chờ tiếp nhận',props.dossiers.filter(x=>x.status==='submitted').length,FileText,'blue'),item('Hồ sơ đã tiếp nhận',s.total,CheckCircle2,'green'),item('Lịch hẹn',props.appointments.length,CalendarDays,'orange'),item('Cần kiểm tra giấy tờ',props.dossiers.filter(x=>x.status==='need_supplement').length,AlertTriangle,'red'),item('Đã trả kết quả',s.completed,Layers3,'purple')]
 case 'officer':return [item('Hồ sơ chờ xử lý',s.waiting,FileText,'blue'),item('Đang xử lý',s.processing,CheckCircle2,'green'),item('Sắp đến hạn',props.dossiers.filter(x=>daysLeft(x.due_at)<=2 && daysLeft(x.due_at)>0 && x.status!=='closed').length,Clock3,'orange'),item('Quá hạn',s.overdue,Clock3,'red'),item('Đã hoàn thành',s.completed,CheckCircle2,'purple')]
 case 'leader':return [item('Tổng hồ sơ tiếp nhận',s.total,FileText,'blue'),item('Đã giải quyết',s.completed,CheckCircle2,'green'),item('Đang xử lý',s.processing,Clock3,'orange'),item('Quá hạn',s.overdue,AlertTriangle,'red'),item('Tỷ lệ đúng hạn',s.total?Math.max(0,Math.round((1-s.overdue/s.total)*100))+'%':'100%',ShieldCheck,'purple')]
 case 'supervisor':return [item('Số đơn vị theo dõi',s.tenants,Building2,'blue'),item('Tổng hồ sơ',s.total,FileText,'green'),item('Đang xử lý',s.processing,Clock3,'orange'),item('Quá hạn',s.overdue,AlertTriangle,'red'),item('Tỷ lệ đúng hạn',s.on_time_rate+'%',CheckCircle2,'purple')]
 default:return [item('Số đơn vị',s.tenants,Users,'blue'),item('Hồ sơ đã giải quyết',s.completed,CheckCircle2,'green'),item('Hồ sơ trong hệ thống',s.total,FileText,'orange'),item('Đang xử lý',s.processing,Clock3,'red'),item('Thủ tục có sẵn',props.procedures.length,Layers3,'purple')]
 }
})
function daysLeft(s:string){return (new Date(s).getTime()-Date.now())/(86400*1000)}
const filtered=computed(()=>props.dossiers.filter(d=>(!search.value || (d.code+d.applicant+d.procedure_code).toLowerCase().includes(search.value.toLowerCase())) &&
 (tab.value==='all'||(tab.value==='waiting'&&d.assigned_role===role.value)||(tab.value==='overdue'&&daysLeft(d.due_at)<0&&!['closed','approved','rejected'].includes(d.status)))))
watch(()=>props.dossiers,async current=>{if(!selected.value&&current.length&&role.value!=='supervisor'&&role.value!=='sys_admin')await choose(current[0]);},{immediate:true})
async function choose(d:Dossier){loading.value=true;try{selected.value=await api('/api/dossiers/'+d.id)}catch(e){selected.value=null}finally{loading.value=false}}
async function refresh(){if(selected.value){const found=props.dossiers.find(d=>d.id===selected.value.id);if(found)await choose(found)}emit('refresh')}
const listTitle=computed(()=>({citizen:'Hồ sơ của tôi',receptionist:'Hàng chờ tiếp nhận',officer:'Công việc của tôi',leader:'Công việc chỉ đạo',supervisor:'Đơn vị cần theo dõi',sys_admin:'Tác vụ quản trị'})[role.value]||'Danh sách hồ sơ')
</script>
<template>
 <div class="stat-grid"><div v-for="(s,i) in headlineStats" :key="s.label" class="stat-card" :class="s.color"><div class="stat-icon"><component :is="s.icon" :size="28" :stroke-width="2"/></div><div class="stat-text"><small>{{s.label}}</small><strong>{{typeof s.value==='number'?s.value.toLocaleString('vi-VN'):s.value}}</strong><small v-if="s.foot">{{s.foot}}</small></div></div></div>
 <div class="dashboard-grid"><section class="panel task-panel"><div class="panel-title"><h2>{{listTitle}} <span v-if="role!=='sys_admin'&&role!=='supervisor'" class="count-dot">{{filtered.length}}</span></h2><button class="round-icon" title="Làm mới" @click="emit('refresh')"><RefreshCw :size="17"/></button></div>
  <template v-if="role==='supervisor'"><div class="tabs"><button class="active">Tất cả ({{crossStats.length}})</button><button @click="emit('navigate','reports')">Cảnh báo</button></div><div class="task-list"><div v-for="s in crossStats" :key="s.tenant_id" class="task-row"><div class="radio-circle"></div><div class="task-copy"><strong>{{s.unit}}</strong><small>Hồ sơ: {{s.total}} · Đúng hạn: {{s.on_time_rate}}%</small></div><span class="status-pill" :class="s.overdue?'danger':'success'">{{s.overdue?'Có quá hạn':'Ổn định'}}</span></div></div><button class="link-row" @click="emit('navigate','reports')">Xem tất cả đơn vị <ArrowRight :size="17"/></button></template>
  <template v-else-if="role==='sys_admin'"><div class="tabs"><button class="active">Toàn hệ thống</button></div><div class="task-list"><div v-for="(name,key) in {tenants:'Quản lý xã / phường',packs:'Kiểm định gói thủ tục',services:'Giám sát dịch vụ',audit:'Kiểm tra sổ cái'}" :key="key" class="task-row clickable" @click="emit('navigate',String(key))"><div class="radio-circle"></div><div class="task-copy"><strong>{{name}}</strong><small>Truy cập chức năng quản trị</small></div><ChevronRight :size="18"/></div></div><button class="link-row" @click="emit('navigate','tenants')">Mở trang quản trị <ArrowRight :size="17"/></button></template>
  <template v-else><div class="tabs"><button :class="{active:tab==='all'}" @click="tab='all'">Tất cả ({{dossiers.length}})</button><button :class="{active:tab==='waiting'}" @click="tab='waiting'">Theo vai trò</button><button :class="{active:tab==='overdue'}" @click="tab='overdue'">Quá hạn</button></div>
    <input v-model="search" class="list-search" placeholder="Tìm mã hồ sơ, thủ tục..." aria-label="Tìm trong danh sách"/>
    <div class="task-list"><button v-for="d in filtered.slice(0,5)" :key="d.id" class="task-row clickable" :class="{selected:selected?.id===d.id}" @click="choose(d)"><span class="radio-circle" :class="{active:selected?.id===d.id}"></span>
      <span class="task-copy"><strong>{{procName(d.procedure_code,procedures)}}</strong><small>{{d.code}} · {{fmtDate(d.received_at)}}</small><small v-if="role!=='citizen'">{{d.applicant}}</small></span><span class="status-pill" :class="statusClass(d.status)">{{statusNames[d.status]}}</span></button>
    <div v-if="!filtered.length" class="empty-mini">Không có hồ sơ phù hợp.</div></div><button class="link-row" @click="emit('navigate','dossiers')">Xem tất cả hồ sơ <ArrowRight :size="17"/></button>
  </template>
 </section>
 <section class="panel detail-panel" v-if="role!=='supervisor'&&role!=='sys_admin'"><DossierDetail :dossier="selected" :role="role" :procedures="procedures" @refresh="refresh"/></section>
 <section v-else class="panel detail-panel"><div class="panel-title"><h2>{{role==='supervisor'?'Tổng hợp tình hình xử lý hồ sơ':'Tình trạng hệ thống'}}</h2><button class="text-link" @click="emit('navigate',role==='supervisor'?'reports':'services')">Xem chi tiết <ArrowRight :size="15"/></button></div>
 <template v-if="role==='supervisor'"><div class="mini-workflow"><div v-for="(x,i) in ['Tiếp nhận','Thẩm định','Trình ký','Ký duyệt','Trả kết quả']" :key="x"><span class="flow-point" :class="i<2?'active':''">{{i<2?'✓':i+1}}</span><small>{{x}}</small></div></div><div class="tabs"><button class="active">Tổng quan</button><button @click="emit('navigate','reports')">Theo đơn vị</button></div><div class="table-scroller"><table class="compact-table"><thead><tr><th>Đơn vị</th><th>Tổng hồ sơ</th><th>Đúng hạn</th><th>Quá hạn</th></tr></thead><tbody><tr v-for="m in crossStats" :key="m.tenant_id"><td>{{m.unit}}</td><td>{{m.total}}</td><td><span class="status-pill success">{{m.on_time_rate}}%</span></td><td><span class="status-pill" :class="m.overdue?'danger':'success'">{{m.overdue}}</span></td></tr></tbody></table></div></template>
 <template v-else><div class="mini-workflow"><div v-for="(x,i) in ['Định danh','Workflow','Kho dữ liệu','Truy xuất tài liệu','API Gateway']" :key="x"><span class="flow-point" :class="i<4?'active':''">{{i<4?'✓':i+1}}</span><small>{{x}}</small></div></div><div class="tabs"><button class="active">Dịch vụ lõi</button><button @click="emit('navigate','tenants')">Đơn vị</button></div><div class="table-scroller"><table class="compact-table"><thead><tr><th>Dịch vụ</th><th>Cấu hình hiện tại</th></tr></thead><tbody><tr v-for="(value,key) in services" :key="key"><td>{{key}}</td><td>{{value}}</td></tr></tbody></table></div><p class="micro-disclaimer">Đây là cấu hình khai báo, chưa phải đo kiểm tình trạng hạ tầng.</p></template></section></div>
 <div class="dashboard-bottom">
 <section class="panel bottom-panel"><div class="panel-title"><h2><component :is="role==='supervisor'?ChartColumn:role==='sys_admin'?Building2:CalendarDays" :size="22" class="blue-text"/> {{role==='citizen'?'Nộp hồ sơ nhanh':role==='supervisor'?'Biểu đồ xu hướng':role==='sys_admin'?'Đơn vị trong hệ thống':role==='leader'?'Báo cáo nhanh':role==='officer'?'Tình hình công việc':'Lịch hẹn tại quầy'}}</h2></div>
 <template v-if="role==='citizen'"><div class="quick-submit"><div class="doc-illustration"><FileText :size="60"/></div><div><h3>Một số thủ tục phổ biến</h3><ul><li v-for="p in procedures.slice(0,4)" :key="p.code">{{p.name}}</li></ul></div><button class="btn primary" @click="emit('navigate','new')"><Plus :size="17"/> Nộp hồ sơ</button></div></template>
 <template v-else-if="role==='receptionist'"><div class="appointment-short"><div v-for="x in appointments.slice(0,3)" :key="x.id"><span class="slot-time">{{new Date(x.slot).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}}</span><strong>{{x.applicant}}</strong><span>— {{procName(x.procedure_code,procedures)}}</span></div></div><button class="link-row" @click="emit('navigate','appointments')">Xem lịch hẹn <ArrowRight :size="16"/></button></template>
 <template v-else-if="role==='officer'||role==='leader'"><div class="report-short"><div><FileText :size="19"/> Báo cáo tình hình giải quyết hồ sơ <ChevronRight :size="17"/></div><div><AlertTriangle :size="19"/> Báo cáo hồ sơ quá hạn và nguyên nhân <ChevronRight :size="17"/></div><div><ShieldCheck :size="19"/> Theo dõi dấu vết xử lý <ChevronRight :size="17"/></div></div><button class="link-row" @click="emit('navigate','reports')">Xem số liệu <ArrowRight :size="16"/></button></template>
 <template v-else><div class="trend-mini"><div><span>Tổng hồ sơ</span><strong>{{stats.total||0}}</strong></div><div><span>Đang xử lý</span><strong>{{stats.processing||0}}</strong></div><div><span>Quá hạn</span><strong>{{stats.overdue||0}}</strong></div></div><button class="link-row" @click="emit('navigate',role==='sys_admin'?'tenants':'reports')">Xem chi tiết <ArrowRight :size="17"/></button></template></section>
 <section class="panel bottom-panel"><div class="panel-title"><h2><BellRing :size="22" class="blue-text"/> {{role==='sys_admin'?'Cảnh báo & Thông báo hệ thống':'Thông báo & Nhắc việc'}}</h2><button class="text-link" @click="emit('navigate','notifications')">Xem tất cả <ArrowRight :size="15"/></button></div>
   <div class="notification-rows"><div><AlertTriangle :size="19" class="danger-text"/><span>{{stats.overdue||0}} hồ sơ đang quá hạn trong phạm vi truy cập</span></div><div><Clock3 :size="19" class="orange-text"/><span>{{stats.processing||0}} hồ sơ đang chờ các bước xử lý</span></div><div><CheckCircle2 :size="19" class="green-text"/><span>{{stats.completed||0}} hồ sơ đã có kết quả/được đóng</span></div></div></section></div>
 <p class="demo-note">Dữ liệu từ API thử nghiệm; số liệu được sinh từ cơ sở dữ liệu mẫu, không phản ánh tình hình thực tế của bất kỳ địa phương nào.</p>
</template>
